cy.intercept('GET', `${API}/comments/1`, {
  statusCode: 200,
  body: {
    id: 1,
    body: 'stubbed body'
  }
}).as('getComment');
cy.get('.network-btn').click();
cy.wait('@getComment').its('request.method').should('eq', 'GET');
